function persistAddressBook(){
    if(!IS_DEMO_EMBED)writeLocalJson(addressBookStorageKey(),{entries:savedAddresses()});
  }

/* Source: shared/lib/orders.js; startInlineDeliveryQuote. Generated by standalone-build.mjs. */
function startInlineDeliveryQuote(){
    clearTimeout(deliveryQuoteTimer);
    clearInterval(deliveryQuoteCountdownTimer);
    const order=flowState.orderState;
    const pickup=order.fulfillmentMode==='pickup';
    const address=order.address || {};
    if(!hasFulfillableItems()) return;
    if(!(order.addressConfirmed && address.building && address.line && address.district)) return;
    if(!pickup && !order.deliveryMethod) return;
    if(pickup || order.deliveryMethod==='postal'){
      order.deliveryQuoteStatus='accepted';
      order.deliveryQuoteAmount=0;
      ensurePaymentDeadline();
      persistFlowState();
      refreshMedicationCheckout();
      return;
    }
    order.deliveryQuoteStatus='calculating';
    order.deliveryQuoteAmount=null;
    persistFlowState();
    refreshMedicationCheckout();
    deliveryQuoteTimer=setTimeout(() => {
      const current=flowState.orderState;
      const amount=current.deliveryMethod==='same-day'
        ? calculatedSameDayDeliveryFee()
        : deliveryFeeFor(current.deliveryMethod);
      current.deliveryQuoteStatus='accepted';
      current.deliveryQuoteAmount=amount;
      ensurePaymentDeadline();
      persistFlowState();
      refreshMedicationCheckout();
    },reduceMotion ? 600 : 3500);
  }

/* Source: shared/lib/address.js; composeDistrict. Generated by standalone-build.mjs. */
function composeDistrict(p){
    return [p.subdistrict, p.districtName, p.province, p.postcode].filter(Boolean).join(' ');
  }

/* Source: shared/lib/intake.js; writeDeliveryAddressDraft. Generated by standalone-build.mjs. */
function writeDeliveryAddressDraft(screen,address){
    if(!screen) return;
    screen.dataset.addressDraft=JSON.stringify({
      building:String(address.building || ''),
      floor:String(address.floor || ''),
      line:String(address.line || ''),
      district:String(address.district || ''),
      note:String(address.note || ''),
      dropoffMethod:String(address.dropoffMethod || 'hand'),
      km:String(address.km || screen.dataset.selectedKm || '3.2')
    });
  }

/* Source: shared/lib/address.js; addressBookKey. Generated by standalone-build.mjs. */
function addressBookKey(address){
    return [address.building,address.line,address.subdistrict,address.districtName,address.postcode]
      .map(part => String(part || '').trim().toLowerCase()).join('|');
  }

/* Source: shared/lib/ui.js; recipientNameParts. Generated by standalone-build.mjs. */
function recipientNameParts(address=flowState.orderState.address){
    const fallback=splitRecipientName(address.recipientName ?? flowState.patientName ?? '');
    return {
      firstName:String(address.recipientFirstName ?? fallback.firstName ?? '').trim(),
      lastName:String(address.recipientLastName ?? fallback.lastName ?? '').trim()
    };
  }

